local StirrupLeatherMaker = {}
local PRODUCTS = {
    iron_stirrup_leather = { name = "Železno usnje za streme", ironCost = 1, woodCost = 1, leatherCost = 5, time = 6, cost = 175, prestige = 4, happiness = 2, description = "Železno usnje za stabilne streme." },
    bronze_stirrup_leather = { name = "Bronasto usnje za streme", bronzeCost = 1, ironCost = 1, woodCost = 1, leatherCost = 5, time = 8, cost = 425, prestige = 6, happiness = 3, description = "Bronasto usnje za lahkotno konjenico." },
    silver_stirrup_leather = { name = "Srebrno usnje za streme", silverCost = 1, bronzeCost = 1, ironCost = 1, woodCost = 1, leatherCost = 5, time = 12, cost = 1025, prestige = 11, happiness = 4, description = "Srebrno usnje za plemiške viteze." },
    gilded_stirrup_leather = { name = "Pozlačeno usnje za streme", goldCost = 1, silverCost = 1, bronzeCost = 1, woodCost = 1, leatherCost = 5, time = 16, cost = 2200, prestige = 20, happiness = 5, description = "Pozlačeno usnje za dvorne konjenike." },
    jewel_set_stirrup_leather = { name = "Draguljasto usnje za streme", goldCost = 2, silverCost = 1, jewelCost = 1, bronzeCost = 1, woodCost = 1, leatherCost = 5, time = 20, cost = 4750, prestige = 36, happiness = 7, description = "Draguljasto usnje za kraljevo konjenico." },
    royal_sovereign_stirrup_leather = { name = "Kraljevski suvereno usnje za streme", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 2, leatherCost = 6, time = 27, cost = 10200, prestige = 70, happiness = 13, description = "Suvereno usnje z biseri za krono." },
}
local BUILDINGS = {
    stirrupleather_workshop = { name = "Stremsko-usnjena delavnica", cost = { gold = 345, wood = 180, stone = 135, iron = 7 }, upkeep = 7, qualityBonus = 5 },
    stirrupleather_house = { name = "Stremsko-usnjena hiša", cost = { gold = 1240, wood = 365, stone = 275, silver = 7, iron = 7 }, upkeep = 26, qualityBonus = 18 },
    master_stirrupleather_atelier = { name = "Mojstrski stremsko-usnjeni atelje", cost = { gold = 3100, wood = 425, stone = 525, silver = 36, gold = 7 }, upkeep = 73, qualityBonus = 30 },
    sovereign_stirrupleather_palace = { name = "Suverena stremsko-usnjena palača", cost = { gold = 13200, wood = 655, stone = 840, gold = 85, jewel = 19 }, upkeep = 258, qualityBonus = 55, prestigeBonus = 50 },
}
StirrupLeatherMaker.ironStock = 10; StirrupLeatherMaker.bronzeStock = 8; StirrupLeatherMaker.woodStock = 12; StirrupLeatherMaker.leatherStock = 22; StirrupLeatherMaker.silverStock = 8; StirrupLeatherMaker.goldStock = 6; StirrupLeatherMaker.jewelStock = 4; StirrupLeatherMaker.pearlStock = 4
StirrupLeatherMaker.productStock = {}; StirrupLeatherMaker.buildings = {}; StirrupLeatherMaker.maker = nil; StirrupLeatherMaker.activeMaking = {}; StirrupLeatherMaker.totalProducts = 0; StirrupLeatherMaker.dayTimer = 0
function StirrupLeatherMaker.init() StirrupLeatherMaker.ironStock=10; StirrupLeatherMaker.bronzeStock=8; StirrupLeatherMaker.woodStock=12; StirrupLeatherMaker.leatherStock=22; StirrupLeatherMaker.silverStock=8; StirrupLeatherMaker.goldStock=6; StirrupLeatherMaker.jewelStock=4; StirrupLeatherMaker.pearlStock=4; StirrupLeatherMaker.productStock={}; StirrupLeatherMaker.buildings={}; StirrupLeatherMaker.maker=nil; StirrupLeatherMaker.activeMaking={}; StirrupLeatherMaker.totalProducts=0; StirrupLeatherMaker.dayTimer=0; print("[StirrupLeatherMaker] Royal Stirrup Leather Maker System initialized (6 products, 4 buildings)") end
function StirrupLeatherMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; StirrupLeatherMaker.maker={name=n or ("Stremar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Stremar najet: %s (spretnost: %d)",StirrupLeatherMaker.maker.name,s),"success") end; return true end
function StirrupLeatherMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function StirrupLeatherMaker.build(id) local ok,e=StirrupLeatherMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(StirrupLeatherMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function StirrupLeatherMaker.getQualityBonus() local b=0; for _,bd in ipairs(StirrupLeatherMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function StirrupLeatherMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and StirrupLeatherMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and StirrupLeatherMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and StirrupLeatherMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and StirrupLeatherMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and StirrupLeatherMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and StirrupLeatherMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and StirrupLeatherMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and StirrupLeatherMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #StirrupLeatherMaker.buildings==0 then return false,"Potrebna stremsko-usnjena delavnica" end; if not StirrupLeatherMaker.maker then return false,"Potreben stremar" end; return true end
function StirrupLeatherMaker.make(pt,qty) qty=qty or 1; local ok,e=StirrupLeatherMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then StirrupLeatherMaker.ironStock=StirrupLeatherMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then StirrupLeatherMaker.bronzeStock=StirrupLeatherMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then StirrupLeatherMaker.woodStock=StirrupLeatherMaker.woodStock-d.woodCost*qty end; if d.leatherCost then StirrupLeatherMaker.leatherStock=StirrupLeatherMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then StirrupLeatherMaker.silverStock=StirrupLeatherMaker.silverStock-d.silverCost*qty end; if d.goldCost then StirrupLeatherMaker.goldStock=StirrupLeatherMaker.goldStock-d.goldCost*qty end; if d.jewelCost then StirrupLeatherMaker.jewelStock=StirrupLeatherMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then StirrupLeatherMaker.pearlStock=StirrupLeatherMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if StirrupLeatherMaker.maker then t=math.max(1,t-math.floor(StirrupLeatherMaker.maker.skill/13)) end; table.insert(StirrupLeatherMaker.activeMaking,{id="stirrupleather_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function StirrupLeatherMaker.completeMaking(m) local q=1.0+(StirrupLeatherMaker.getQualityBonus()/100); if StirrupLeatherMaker.maker then q=q+(StirrupLeatherMaker.maker.skill/140) end; q=math.min(2.5,q); StirrupLeatherMaker.productStock[m.productType]=(StirrupLeatherMaker.productStock[m.productType] or 0)+m.quantity; StirrupLeatherMaker.totalProducts=StirrupLeatherMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if StirrupLeatherMaker.maker then StirrupLeatherMaker.maker.itemsMade=StirrupLeatherMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then StirrupLeatherMaker.maker.skill=math.min(100,StirrupLeatherMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Usnje izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"stirrupleather.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function StirrupLeatherMaker.update(dt) if not _G.state then return end; StirrupLeatherMaker.dayTimer=StirrupLeatherMaker.dayTimer+dt; if StirrupLeatherMaker.dayTimer>=30 then StirrupLeatherMaker.dayTimer=0; for i=#StirrupLeatherMaker.activeMaking,1,-1 do local m=StirrupLeatherMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then StirrupLeatherMaker.completeMaking(m); table.remove(StirrupLeatherMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(StirrupLeatherMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if StirrupLeatherMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function StirrupLeatherMaker.getStats() return {ironStock=StirrupLeatherMaker.ironStock,bronzeStock=StirrupLeatherMaker.bronzeStock,woodStock=StirrupLeatherMaker.woodStock,leatherStock=StirrupLeatherMaker.leatherStock,silverStock=StirrupLeatherMaker.silverStock,goldStock=StirrupLeatherMaker.goldStock,jewelStock=StirrupLeatherMaker.jewelStock,pearlStock=StirrupLeatherMaker.pearlStock,productStock=StirrupLeatherMaker.productStock,numBuildings=#StirrupLeatherMaker.buildings,hasMaker=StirrupLeatherMaker.maker~=nil,makerName=StirrupLeatherMaker.maker and StirrupLeatherMaker.maker.name or "—",makerSkill=StirrupLeatherMaker.maker and StirrupLeatherMaker.maker.skill or 0,activeMaking=#StirrupLeatherMaker.activeMaking,totalProducts=StirrupLeatherMaker.totalProducts} end
return StirrupLeatherMaker
